           autocomplete: "name",
           required: true,
           error: "Enter your full name."
         },
         {
           id: "email-address",
           name: "email",
           label: "Email address",
           type: "email",
           autocomplete: "email",
           required: true,
           error: "Enter a valid email address."
         },
         {
           id: "phone-number",
           name: "phone",
           label: "Phone number",
           type: "tel",
           autocomplete: "tel",
           required: false,
           helperText: "Use international format, for example +1 555 123 4567."
         }
       ];

       function escapeHtml(value) {
         return String(value)
           .replaceAll("&", "&amp;")
           .replaceAll("<", "&lt;")
           .replaceAll(">", "&gt;")
           .replaceAll('"', "&quot;");
       }

       function FormField({ id, name, label, type, autocomplete, required, helperText }) {
         const helperId = helperText ? `${id}-helper` : "";
         const errorId = `${id}-error`;
         const describedBy = [helperId, errorId].filter(Boolean).join(" ");

         return `
           <div class="form-field">
             <label for="${id}">
               ${escapeHtml(label)}${required ? ' <span class="required-marker" aria-hidden="true">*</span>' : ""}
             </label>
             <input
               id="${id}"
               name="${name}"
               type="${type}"
               autocomplete="${autocomplete}"
               ${required ? "required" : ""}
               ${describedBy ? `aria-describedby="${describedBy}"` : ""}
             >
             ${helperText ? `<p class="helper-text" id="${helperId}">${escapeHtml(helperText)}</p>` : ""}
             <p class="error-message" id="${errorId}"></p>
           </div>
         `;
       }

       function ContactForm() {
         return `
           <section class="support-card" aria-labelledby="support-form-heading">
             <h2 id="support-form-heading">Contact support</h2>
             <p>Tell us where to reach you and our team will follow up.</p>
             <div class="validation-summary" id="validation-summary" role="status" aria-live="polite"></div>
             <form id="support-form" novalidate>
               ${fields.map(FormField).join("")}
               <button type="submit">Send support request</button>
             </form>
           </section>
         `;
       }

       function App() {
         return `
           <div class="page-shell">
             <header>
               <p class="brand">Support Center</p>
             </header>
             <main id="main-content">
               <section class="hero" aria-labelledby="page-title">
                 <h1 id="page-title">How can we help?</h1>
                 <p>
                   Share your contact details and a support specialist will reach out with the next steps.
                 </p>
               </section>
               ${ContactForm()}
             </main>
           </div>
         `;
       }

       function setFieldError(input, message) {
         const errorElement = document.getElementById(`${input.id}-error`);
         input.setAttribute("aria-invalid", message ? "true" : "false");
         errorElement.textContent = message;
       }

       function validateForm(form) {
         let firstInvalid = null;

         fields.forEach((field) => {
           const input = form.elements[field.name];
           let message = "";

           if (field.required && !input.value.trim()) {
             message = field.error;
           } else if (field.type === "email" && input.value && !input.validity.valid) {
             message = field.error;
           }

           setFieldError(input, message);

           if (message && !firstInvalid) {
             firstInvalid = input;
           }
         });

         return firstInvalid;
       }

       function attachFormBehavior() {
         const form = document.getElementById("support-form");
         const summary = document.getElementById("validation-summary");

         form.addEventListener("input", (event) => {
           const input = event.target;
           if (input instanceof HTMLInputElement && input.getAttribute("aria-invalid") === "true") {
             setFieldError(input, "");
             summary.textContent = "";
           }
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           const firstInvalid = validateForm(form);

           if (firstInvalid) {
             summary.textContent = "Please fix the highlighted fields before sending your request.";
             firstInvalid.focus();
             return;
           }

           summary.textContent = "Thanks. Your support request is ready to send.";
           form.reset();
         });
       }

       document.getElementById("root").innerHTML = App();
       attachFormBehavior();
     </script>
   </body>
 </html>

')
